use chrono::{DateTime, Utc}; use reqwest::Client; use serde_json::{json, Value}; use std::time::Duration; use thiserror::Error;
#[derive(Debug, Error)] pub enum RpcError { #[error("no RPC endpoint succeeded: {0}")] Unavailable(String), #[error("HTTP client: {0}")] Http(#[from] reqwest::Error), #[error("invalid RPC response: {0}")] Invalid(String) }
#[derive(Clone)] pub struct RpcPool { client: Client, endpoints: Vec<String>, timeout: Duration }
#[derive(Debug, Clone)] pub struct RpcObservation { pub value: Value, pub observed_at: DateTime<Utc>, pub received_at: DateTime<Utc> }
impl RpcPool { pub fn new(endpoints: Vec<String>, timeout: Duration) -> Result<Self, RpcError> { let client=Client::builder().timeout(timeout).build()?; Ok(Self{client,endpoints,timeout}) } pub async fn call(&self, method: &str, params: Value) -> Result<RpcObservation,RpcError> { let observed_at=Utc::now(); let mut errors=Vec::new(); for endpoint in &self.endpoints { let body=json!({"jsonrpc":"2.0","id":1,"method":method,"params":params}); match self.client.post(endpoint).json(&body).send().await { Ok(r) => match r.json::<Value>().await { Ok(v) if v.get("error").is_none() => return Ok(RpcObservation{value:v["result"].clone(),observed_at,received_at:Utc::now()}), Ok(v)=>errors.push(format!("{endpoint}: {}",v["error"])),Err(e)=>errors.push(format!("{endpoint}: {e}")) }, Err(e)=>errors.push(format!("{endpoint}: {e}")) } } Err(RpcError::Unavailable(errors.join("; "))) } pub async fn health(&self)->Result<(),RpcError>{self.call("getHealth",json!([])).await.map(|_|())} pub async fn balance_lamports(&self,address:&str)->Result<u64,RpcError>{let v=self.call("getBalance",json!([address,{"commitment":"confirmed"}])).await?;v.value["value"].as_u64().ok_or_else(||RpcError::Invalid("missing balance value".into()))} }
